import { usePlane } from "@react-three/cannon";
import { useRef } from "react";
export default function CannonPlane({ debug, args, children, ...props }) {
  const [ref] = usePlane(
    () => ({ material: "ground", type: "Kinematic", ...props }),
    useRef(null)
  );
  return (
    <group ref={ref}>
      {debug && (
        <mesh ref={ref} castShadow receiveShadow >
          <planeGeometry args={args} />
          <meshLambertMaterial color="black" />
        </mesh>
      )}
      {children}
    </group>
  );
}
