import React from "react";
import jsonData from "../../json/data.json";
import { useSnapshot } from "valtio";
import state from "../../store";
import Contactbar from "../../components/contact";
import TransitionLink from "../../hooks/TransitionLink";
const Author = ({ children, ...props }) => {
  const snap = useSnapshot(state);
  return (
    <div className="flex items-center justify-center w-full h-full mt-10 flex-col">
      <section className="flex-[30%] text-lg">
        <section className="z-10 flex flex-col justify-center items-center">
          <div className=" object-cover rounded-full scale-[1.05] -translate-y-9 transition-all cursor-pointer relative">
            <div className="w-full h-full absolute object-contain rounded-full bottom-0 duration-1000 transition-all left-0 translate-y-2 bg-gray-900/10 scale-x-[1.05] scale-y-[.99]"></div>
           <TransitionLink to='/'> <img
              className="h-[290px] w-[290px] object-cover scale-[1.05] rounded-full top-0 duration-700 transition-all z-10 contrast-125 brightness-95"
              src={snap.authorsPicTbk}
              alt="author:David Grant"
              title="David Grant"
            /></TransitionLink>
          </div>

          <span className="flex items-center flex-col">
            <span className="text-3xl sm:text-4xl text-gradB">
              {props?.title || jsonData.title}
            </span>
            <span className="text-7xl text-gradB Alfa text-center">
              {jsonData.name}
            </span>
          </span>
          <div className="my-5">
            <Contactbar size={"24px"} />
          </div>
        </section>
        {children}
      </section>
    </div>
  );
};

export default Author;
