export default function TextureOptions(folder) {
  return {
    heightMapSrc: `/assets/${folder}/height.jpg`,
    normalMapSrc: `/assets/${folder}/normal.jpg`,
    edgeMapSrc: `/assets/${folder}/edge.jpg`,
    smoothMapSrc: `/assets/${folder}/smoothness.jpg`,
    AO: `/assets/${folder}/ao.jpg`,
    textureMapSrc: `/assets/${folder}/diffuseOriginal.jpg`,
    metallicMapSrc: `/assets/${folder}/metallic.jpg`,
  };
}
