import React, { useRef } from "react";
import Author from "../pages/corporate/author";
import Logo from "../components/Logo";
import Navigation from "../components/navigation";
import CircleSvg from "../components/circlesvg";
import { MouseParallax } from "react-just-parallax";
import { useLocation } from "react-router-dom";
export default function LayoutContainer({ children }) {
  const containerRef = useRef();
  const { pathname } = useLocation();
  const classColor = () => {
    switch (pathname) {
      case "/":
        return "text-white blur-sm";
      case "/about":
        return "text-white/30 scale-150 blur-xl";
      case "/work":
        return "text-gray-200 blur-lg";
      default:
        return "text-white";
    }
  };
  return (
    <div className="intro_animation inline-flex flex-col justify-center items-center">
      <Logo />
      <div className="inline-flex flex-col justify-center items-center z-10 m-0 bg-white/40 shadow-md relative rounded-xl">
        <section
          ref={containerRef}
          className="inline-flex flex-col xl:w-full  max-w-5xl px-4 "
        >
          <Author id="home">
            <Navigation />
            {children}
          </Author>
        </section>
        <div className="absolute backdrop-blur-2xl rounded-none xl:rounded-xl p-4 w-full h-full top-0 left-0 z-[-1] transition-all bg-white/2"></div>
        <MouseParallax
          strength={0.05}
          isAbsolutelyPositioned={true}
          zIndex={-2}
          parallaxContainerRef={containerRef}
          enableOnTouchDevice={false}
        >
          <div
            className={`${classColor()} absolute w-1/2 h-1/2 bottom-0 xl:left-2/3 left-0 z-[-2] transition-all`}
          >
            <CircleSvg />
          </div>
        </MouseParallax>
        <MouseParallax
          strength={-0.05}
          isAbsolutelyPositioned={true}
          zIndex={-2}
          parallaxContainerRef={containerRef}
          enableOnTouchDevice={false}
        >
          <div
            className={`${classColor()} transition-all absolute w-1/2 h-1/2 top-0 xl:right-2/3 right-0 z-[-2] rotate-180 overflow-hidden`}
          >
            <CircleSvg />
          </div>
        </MouseParallax>
      </div>
    </div>
  );
}
