import React from "react";
import jsonData from "../json/data.json";
const Logo = ({ ...props }) => {
  return (
    <section
      className="flex flex-col relative xl:fixed z-0 left-0 top-0 items-center w-full xl:w-auto"
      {...props}
    >
      <h1 className="text-center flex-1 portfolio-title min-h-screen  relative hidden xl:block transition-all ">
        {jsonData.logo}
      </h1>

      <h1 className="text-center flex-1 portfolio-title-mobile mb-10 relative block xl:hidden transition-all w-full">
        {jsonData.logo}
      </h1>
    </section>
  );
};
export default Logo;
