import React from "react";
import jsonData from "../json/data.json";
import TransitionLink from "../hooks/TransitionLink";
const Navigation = ({ ...props }) => {
  return (
    <nav className="flex justify-center transition-all">
      <ul className="cursor-pointer text-gradB inline-flex justify-between gap-4 w-auto p-4 rounded-full">
        {jsonData.menu.map(({ title, route, external }, key) => (
          <li
            key={key}
            className="Anuphan text-2xl hover:scale-110 transition-all gradient_purple_text"
          >
            {external ? (
              <TransitionLink href={route}>{title}</TransitionLink>
            ) : (
              <TransitionLink to={route}>{title}</TransitionLink>
            )}
          </li>
        ))}
      </ul>
    </nav>
  );
};
export default Navigation;
