import React, { Suspense, useMemo } from "react";
import {
  OrbitControls,
  Loader,
  PerspectiveCamera,
} from "@react-three/drei";
import { Canvas } from "@react-three/fiber";
import { space, transitionViewIfSupported } from "../utils/";
import {
  EffectComposer,
  DepthOfField,
  Bloom,
  Noise,
  Vignette,
} from "@react-three/postprocessing";
import { useNavigate } from "react-router-dom";
import { Physics } from "@react-three/cannon";
import CreateText from "../three/CreateText";
import PageNotFound from "../cannon/pagenotFound";
import CannonPlane from "../cannon/plane";
import GeoPlaneShader from "../three/GeoPlaneShader";
import { SimpleShader } from "../shaders/CloudyTunnelShader";
import { SimpleShader as simp } from "../shaders/FireShader";
import TextureOptions from "../hooks/TextureOptioins";
export default function Error() {
  const navigate = useNavigate();
  const sharedData = useMemo(
    () => ({
      position: [(7 * 60 + 100) / 2, -10, 0],
      rotation: [Math.PI / 2, 0, 0],
      scale: [1, 1, 1],
      bumpScale: 0.5,
      rows: 6,
      columns: 5,
      args: [100, 205, 16, 16],
      ...TextureOptions("textures/moon"),
    }),
    []
  );
  const maxWidth = window.innerWidth;
  const maxHeight = window.innerHeight;
  return (
    <div className="moon fixed top-0 left-0 z-[100] flex h-screen w-screen flex-col items-center justify-center">
      <Suspense fallback={<Loader />}>
        <Canvas id='background-image' performance={{ min: 0.5 }} flat linear shadows>
          <PerspectiveCamera
            makeDefault
            fov={75}
            far={1000}
            near={0.01}
            position={[0, space(5), space(15)]}
            aspect={window.innerWidth / window.innerHeight}
          />
          <ambientLight color="white" intensity={0.25} />
          <GeoPlaneShader
            {...sharedData}
            position={[0, space(72.1), space(-90)]}
            rotation={[0, 0, 0]}
            smokeScale={[maxWidth, maxHeight]}
            args={[maxWidth, 470, 1, 1]}
            speed={0.00265}
            shader={SimpleShader}
            castShadow
          />
          {/* <OrbitControls
            minPolarAngle={space(0.24)}
            maxPolarAngle={space(0.4)}
            maxAzimuthAngle={space(0.5)}
            minAzimuthAngle={space(-0.5)}
            maxDistance={space(20)}
            minDistance={space(12)}
            enablePan={false}
          /> */}
          <Physics
            defaultContactMaterial={{
              contactEquationRelaxation: 0.4,
              friction: 1e-3,
              restitution: 0.01,
            }}
            gravity={[0, -24, 0]}
            allowSleep
          >
            <PageNotFound />

            <CannonPlane
              rotation={[-space(0.5), 0, 0]}
              position={[0, space(-3), 0]}
              userData={{ id: "floor" }}
            >
              <GeoPlaneShader
                {...sharedData}
                position={[0, 0, 0]}
                rotation={[0, 0, 0]}
                smokeScale={[maxWidth, maxHeight]}
                args={[maxWidth, maxHeight, 1, 1]}
                speed={0.00001265}
                shader={simp}
                castShadow
              />
            </CannonPlane>
            <group
              position={[0, 0, 0]}
              onClick={() => {
                transitionViewIfSupported(navigate("/"));
              }}
            >
              <CreateText
                textstring="<-Back"
                fontSize={3}
                fontHeight={0.3}
                position={[space(-3), space(5), 0]}
                color="#fff"
              />
            </group>
          </Physics>

          <EffectComposer>
            <DepthOfField
              focusDistance={7}
              focalLength={92}
              bokehScale={5}
              height={80}
            />
            <Bloom
              luminanceThreshold={400}
              luminanceSmoothing={90}
              height={30}
            />
            <Noise opacity={0.05} />
            <Vignette eskil={true} offset={0.0} darkness={1.1} />
          </EffectComposer>
        </Canvas>
      </Suspense>
    </div>
  );
}
