import React, { useMemo } from "react";
import { extend } from "@react-three/fiber";
import { FontLoader } from "three/examples/jsm/loaders/FontLoader";
import { TextGeometry } from "three/examples/jsm/geometries/TextGeometry";
import comfortia from "../fonts/Comfortaa.json";
import pressstart from "../fonts/PressStart2P.json";
import { space } from "../utils";
import { Color } from "three";

extend({ TextGeometry });
const CreateText = ({
  textstring = "test",
  fontType = "",
  fontSize = 6,
  fontHeight = 1,
  textDistance = 2.5,
  hover = "#fff",
  color = "#000",
  hasBackrgound=true,
  ...props
}) => {
  const font = useMemo(() => {
    switch (fontType) {
      case "c":
        return new FontLoader().parse(comfortia);
      default:
        return new FontLoader().parse(pressstart);
    }
  }, [fontType]);
  return (
    <group {...props}>
      {[...textstring].map((letter, index) => (
        <group
          className=""
          key={index}
          position={[space(index * (fontSize / textDistance)), 0, 0]}
          onPointerEnter={(e) =>
            (e.eventObject.children[0].material.color = new Color(hover))
          }
          onPointerLeave={(e) =>
            (e.eventObject.children[0].material.color = new Color(color))
          }
        >
          <mesh position={[0, 0, 0]} name="text">
            <textGeometry
              attach="geometry"
              args={[
                letter,
                { font: font, size: fontSize, height: fontHeight },
              ]}
            />
            <meshPhysicalMaterial attach="material" color={new Color(color)} />
          </mesh>
          {hasBackrgound && <mesh
            name="hover"
            position={[fontSize * (textDistance / 5), fontSize * (textDistance / 5), 0]}
          >
            <planeGeometry
              attach="geometry"
              args={[fontSize, fontSize, fontSize]}
            />
            <meshLambertMaterial transparent color={[0, 0, 0]} opacity={0} />
          </mesh>}
        </group>
      ))}
    </group>
  );
};
export default CreateText;
