export const noSpace = text => text.replace(/\s+/g, "-").toLowerCase();
export const json = response => response.json();
export const noJson = response => response;
export const justData = response => response.data;
export const error = error => console.error(error);

export const status = response => {
  if (response.status >= 200 && response.status < 300) {
      return Promise.resolve(response);
  } else {
      window.errors = new Error(response.statusText)
      return Promise.reject(new Error(response.statusText));
  }
};

export const returnArray = (number) => {
  return Array.apply(null, { length: number }).map(Function.call, Number);
};

export const daysInMonth = (Month, Year) => {
  return 32 - new Date(Year, Month, 32).getDate();
};
export const firstDayOfMonth = (Month, Year) => {
  return new Date(Year, Month, 1).getDay();
};


export const getPostValues = e => {
  const {
      target,
      target: { form },
      target: {
          form: { elements }
      }
  } = e;
  return getFormData(elements);
}

export const getFormData = elements => {
  const formDataValue = new FormData();
  let list = [].slice.call(elements, 0);
  list.map(x => formDataValue.append(x.name, x.value));
  console.log({list},list.length)
  return formDataValue
};


export async function createAudio(url) {
  // Fetch audio data and create a buffer source
  const res = await fetch(url)
  const buffer = await res.arrayBuffer()
  const context = new (window.AudioContext || window.webkitAudioContext)()
  const source = context.createBufferSource()
  source.buffer = await new Promise((res) => context.decodeAudioData(buffer, res))
  source.loop = true
  // This is why it doesn't run in Safari 🍏🐛. Start has to be called in an onClick event
  // which makes it too awkward for a little demo since you need to load the async data first
  source.start(0)
  // Create gain node and an analyser
  const gain = context.createGain()
  const analyser = context.createAnalyser()
  analyser.fftSize = 64
  source.connect(analyser)
  analyser.connect(gain)
  // The data array receive the audio frequencies
  const data = new Uint8Array(analyser.frequencyBinCount)
  return {
    context,
    source,
    gain,
    data,
    // This function gets called every frame per audio source
    update: () => {
      analyser.getByteFrequencyData(data)
      // Calculate a frequency average
      return (data.avg = data.reduce((prev, cur) => prev + cur / data.length, 0))
    },
  }
}

export const PI = Math.PI
export const space = (n) => n * PI; 

export const transitionViewIfSupported = (updateCb) => {
  if (document.startViewTransition) {
    document.startViewTransition(updateCb);
  } else {
    updateCb();
  }
};