import React from "react";
import { space } from "../utils";
import CannonBox from "../cannon/box";
import CreateText from "../three/CreateText";
export default function PageNotFound() {
  const errorTextOptions = {
    color: "rgba(0,0,0,1)",
    hover: "rgba(255,255,255,1)",
    fontSize: 8,
    fontHeight: 3,
    hasBackrgound: false,
    // fontType:"c"
  };
  const errorBoxOptions = {
    // type: Math.random() * 1 > 0.5 ? "Kinematic" : "Dynamic",
    type:"Static",
    mass: 1,
    // debug: true,
  };
  const textPosition = {
    page: -10,
    not: -1,
    found: 7,
  };
  return (
    <>
      <CannonBox
        mass={10}
        args={[30, 9, 2]}
        position={[space(Math.random() * -16), space(Math.random()*50), 0]}
      >
        <CreateText
          textstring={`404`}
          position={[space(-4.75), space(-2), space(-0.5)]}
          {...errorTextOptions}
        />
      </CannonBox>
      <CannonBox
        args={[10, 9, 2]}
        position={[space(textPosition.page - 6.5), space(0), 0]}
        {...errorBoxOptions}
      >
        <CreateText
          textstring={`P`}
          {...errorTextOptions}
          position={[space(-1.5), space(-2), space(-0.5)]}
        />
      </CannonBox>
      <CannonBox
        args={[30, 6, 2]}
        position={[space(textPosition.page), space(0), 0]}
        {...errorBoxOptions}
      >
        <CreateText
          textstring={`age`}
          {...errorTextOptions}
          position={[space(-4.6), space(-1.5), space(-0.5)]}
        />
      </CannonBox>
      <CannonBox
        args={[20, 7, 2]}
        position={[space(textPosition.not), space(0), 0]}
        {...errorBoxOptions}
      >
        <CreateText
          textstring={`no`}
          {...errorTextOptions}
          position={[space(-3.1), space(-1.5), space(-0.5)]}
        />
      </CannonBox>
      <CannonBox
        args={[8, 9, 2]}
        position={[space(textPosition.not + 4.5), space(0.4), 0]}
        {...errorBoxOptions}
      >
        <CreateText
          textstring={`t`}
          {...errorTextOptions}
          position={[space(-1.75), space(-2), space(-0.5)]}
        />
      </CannonBox>
      <CannonBox
        args={[10, 9, 2]}
        position={[space(textPosition.found), space(0.4), 0]}
        {...errorBoxOptions}
      >
        <CreateText
          textstring={`f`}
          {...errorTextOptions}
          position={[space(-2), space(-2), space(-0.5)]}
        />
      </CannonBox>
      <CannonBox
        args={[28, 7, 2]}
        position={[space(textPosition.found + 6), space(0), 0]}
        {...errorBoxOptions}
      >
        <CreateText
          textstring={`oun`}
          {...errorTextOptions}
          position={[space(-4.7), space(-1.6), space(-0.5)]}
        />
      </CannonBox>
      <CannonBox
        args={[10, 9, 2]}
        position={[space(textPosition.found + 12.7), space(0.4), 0]}
        {...errorBoxOptions}
      >
        <CreateText
          textstring={`d`}
          {...errorTextOptions}
          position={[space(-2), space(-2), space(-0.5)]}
        />
      </CannonBox>
    </>
  );
}
