import {
  // sRGBEncoding,
  RepeatWrapping,
} from 'three'
import { useTexture } from '@react-three/drei'
export default function FormatTexture(texture) {
    const textureMap = useTexture(texture)
    // textureMap.colorSpace = sRGBEncoding
    textureMap.wrapS = RepeatWrapping
    textureMap.wrapT = RepeatWrapping
    textureMap.anisotropy = 32
  return textureMap
}
