import { useBox } from "@react-three/cannon";
import { useRef } from "react";
export default function CannonBox({
  debug = false,
  children,
  args,
  mass = 1,
  ...props
}) {
  const [ref] = useBox(
    () => ({ args: args, mass: mass, type: "Dynamic", ...props }),
    useRef(null)
  );
  return (
    <group ref={ref} {...props}>
      {debug && (
        <mesh ref={ref} castShadow receiveShadow>
          <boxBufferGeometry args={args} />
          <meshLambertMaterial color="white" />
        </mesh>
      )}
      {children}
    </group>
  );
}
