import React, { Suspense } from "react";
import PageRouter from "./components/page_router";
import Loader from "./components/Loader";
import LayoutContainer from "./components/layout_container";
export default function App() {
  return (
    <main className="flex items-center justify-center relative min-h-screen transition-all">
      <Suspense fallback={<Loader />}>
        <LayoutContainer>
          <PageRouter />
        </LayoutContainer>
        <div className='bg-white z-[-2] transition-all fixed w-screen h-screen left-0 top-0 overflow-hidden grad-background scale-110' />
      </Suspense>
    </main>
  );
}
