import React, { useRef } from 'react'
import { useFrame } from '@react-three/fiber'
import {
  DoubleSide,
  Vector2,
} from 'three'
import FormatTexture from '../hooks/FormatTexture'
const GeoPlaneShader = ({
  heightMapSrc,
  AO,
  bumpScale,
  smokeScale,
  textureMapSrc,
  shader,
  speed,
  args,
  ...props
}) => {
  const { fragmentShader, vertexShader } = shader
  const heightMap = FormatTexture(heightMapSrc)
  const AoTextureMap = FormatTexture(AO)
  const textureMap = FormatTexture(textureMapSrc)
  const TerrainMaterialRef = useRef()
  useFrame(({ clock }, delta) => {
    if (TerrainMaterialRef?.current) {
      TerrainMaterialRef.current.material.uniforms.u_time.value =
        performance.now() * speed
      TerrainMaterialRef.current.material.uniforms.u_time.needsUpdate = true
      TerrainMaterialRef.current.uniformsNeedUpdate = true
    }
  })
  return (
    
      <mesh {...props} ref={TerrainMaterialRef} transparent={true}>
        {/* */}
        <planeGeometry
          attach='geometry'
          args={args}
          receiveShadow
          transparent={true}
        />
        <shaderMaterial
          attach='material'
          // Feed the shaders as strings
          uniforms={{
            bumpTexture: { value: heightMap },
            bumpScale: { value: bumpScale || 1.0 },
            terrainTexture: { value: textureMap },
            iChannel0: { value: AoTextureMap },
            iChannel1: { value: textureMap },
            u_time: { type: 'f', value: 0.05 },
            u_speed: { type: 'f', value: speed },
            u_mouse: { type: 'f', value: { x: 0, y: 0 } },
            u_resolution: {
              type: 'v2',
              value: new Vector2(smokeScale[0], smokeScale[1])
            }
          }}
          transparent={true}
          uniformsNeedUpdate={true}
          vertexShader={vertexShader}
          fragmentShader={fragmentShader}
          side={DoubleSide}
        />
      </mesh>
    
  )
}
export default GeoPlaneShader
